// Atom order is retained. Uracil has no thymine C7. O2 is distinct from ribose O2'.
// Scalar torsions are signed geometrical torsions, like x3DNA torsion2(),
// without torsion()'s covalent-distance gate (several survey terms are proxies).
const freezeDeep = value => { if (value && typeof value === 'object') { for (const child of Object.values(value)) freezeDeep(child); Object.freeze(value); } return value; };

