export const LOCAL_FRAME_RECIPES = freezeDeep([{frame_id:'rna_standard_base', display_name:'RNA standard base frame', anchor_bases:['A','C','G','U'], source:'x3DNA Atomic_A/C/G/U.pdb'}, {frame_id:'cytosine_standard_pair', display_name:'Cytosine standard frame (CG pair)', anchor_bases:['C'], sequence_contexts:['C-G','G-C'], source:'x3DNA Atomic_C.pdb', notes:'Standard base frame; not the DNA N1-C2 plane recipe.'}]);
export function enabledScalarTerms() { return TERM_REGISTRY.filter(term => term.enabled); }
export function publicTermRegistry() { return structuredClone(TERM_REGISTRY); }
export function publicBaseGeometryConfig() { return structuredClone({terms:TERM_REGISTRY, base_atoms:BASE_ATOMS, opening_bins:OPENING_BINS, local_frame_recipes:LOCAL_FRAME_RECIPES}); }
export function openingBinForValue(value, bins=OPENING_BINS) {
  if (!Number.isFinite(value)) return 'missing';
  for (const bin of bins) {
    if (bin.min == null || bin.max == null) continue;
    if ((bin.include_min ? value >= bin.min : value > bin.min) && (bin.include_max ? value <= bin.max : value < bin.max)) return bin.id;
  }
  return 'outside';
}
